theme.css:
/* theme: Amber Breathe | A rebound after days of red, with oil sliding and rates rising — markets exhale but the world stays coiled in amber suspense. */
/* mood: tense */
/* layout: hero=split; political-news=lede/stack; financial-news=stat/stack; entertainment-news=tile/grid-2; sports=outline/grid-2; music-releases=plain/stack; stock-analysis=numbered/grid-3; outlook=timeline/stack */

.diary-page {
  --paper: #fbf0d9;
  --paper-alt: #f2e0be;
  --ink: #1f1607;
  --ink-soft: #3a2c14;
  --muted: #6b5736;
  --accent: #a34a00;
  --accent-ink: #fffaf0;
  --rule: #d9c496;
  --font-display: var(--ff-bebas), sans-serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-inter), system-ui, sans-serif;
}

.diary-page {
  min-height: 100vh;
  background:
    linear-gradient(180deg, transparent 0%, transparent 60%, rgba(163, 74, 0, 0.06) 100%),
    var(--paper);
}

.diary-page .diary-hero-inner {
  border-bottom: 3px solid var(--accent);
  padding-bottom: 2.5rem;
  position: relative;
}

.diary-page .diary-hero-inner::before {
  content: "▲";
  position: absolute;
  right: 0.5rem;
  top: 0.5rem;
  font-size: 2.5rem;
  color: var(--accent);
  opacity: 0.3;
}

.diary-page .diary-kicker {
  font-family: var(--font-ui);
  letter-spacing: 0.3em;
  font-weight: 700;
  color: var(--accent);
}

.diary-page .diary-title {
  font-family: var(--font-display);
  letter-spacing: 0.04em;
  text-transform: uppercase;
  font-size: clamp(2.75rem, 8vw, 6.5rem);
  color: var(--ink);
  line-height: 0.95;
  max-width: 14ch;
}

.diary-page .diary-summary {
  font-style: italic;
  color: var(--ink-soft);
  border-left: 4px solid var(--accent);
  padding-left: 1.25rem;
}

.diary-page .diary-theme-note {
  font-family: var(--font-ui);
  letter-spacing: 0.05em;
}

.diary-page .diary-theme-name {
  background: var(--accent);
  color: var(--accent-ink);
  border-radius: 0;
  font-weight: 700;
  text-transform: uppercase;
  font-size: 0.75rem;
}

.diary-page .diary-toc {
  background: rgba(251, 240, 217, 0.95);
}

.diary-page .diary-toc-number,
.diary-page .diary-toc-link.is-active {
  color: var(--accent);
  font-weight: 700;
}

.diary-page .diary-toc-list {
  border-left: 1px solid var(--rule);
}

.diary-page .diary-toc-link.is-active {
  border-left-color: var(--accent);
}

.diary-page .diary-section-head {
  border-bottom: 2px solid var(--accent);
  padding-bottom: 0.6rem;
  margin-bottom: 2rem;
}

.diary-page .diary-section-number {
  font-family: var(--font-ui);
  font-size: 0.85rem;
  font-weight: 700;
  letter-spacing: 0.2em;
  color: var(--accent);
}

.diary-page .diary-section-title {
  font-family: var(--font-display);
  text-transform: uppercase;
  letter-spacing: 0.03em;
  font-size: clamp(2.25rem, 4vw, 3.5rem);
  color: var(--ink);
}

.diary-page .diary-prose {
  font-size: 1.1rem;
  line-height: 1.75;
  color: var(--ink-soft);
}

.diary-page .diary-prose strong {
  color: var(--ink);
}

.diary-page .diary-prose a {
  color: var(--accent);
  border-bottom: 1px solid rgba(163, 74, 0, 0.4);
}

.diary-page .diary-prose blockquote {
  border-left-color: var(--accent);
  color: var(--ink);
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
  width: 0.8rem;
}

.diary-page .diary-card--lede .diary-card-inner {
  padding-left: 2rem;
  border-left: 6px solid var(--accent);
  background: linear-gradient(90deg, rgba(163, 74, 0, 0.05), transparent);
}

.diary-page .diary-card-lede {
  border-left: 0;
  font-family: var(--font-display);
  font-size: 1.8rem;
  line-height: 1.2;
  letter-spacing: 0.02em;
  color: var(--ink);
  text-transform: uppercase;
  padding-left: 0;
}

.diary-page .diary-card--stat .diary-card-inner {
  border-top: 6px solid var(--accent);
}

.diary-page .diary-card-figure {
  font-family: var(--font-display);
  font-size: clamp(3.5rem, 15cqi, 6rem);
  letter-spacing: 0.02em;
  color: var(--accent);
}

.diary-page .diary-card--tile .diary-card-inner {
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.3), transparent 50%),
    var(--paper-alt);
  border: 1px solid var(--rule);
  box-shadow: 0 8px 24px -12px rgba(163, 74, 0, 0.15);
}

.diary-page .diary-card--tile .diary-card-title {
  font-family: var(--font-display);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-size: 1.6rem;
  color: var(--ink);
}

.diary-page .diary-card--outline .diary-card-inner {
  border: 2px solid var(--rule);
  border-radius: 0;
  background: transparent;
  transition: box-shadow 200ms;
}

.diary-page .diary-card--outline .diary-card-inner:hover {
  box-shadow: 0 12px 32px -16px rgba(163, 74, 0, 0.25);
}

.diary-page .diary-card--outline .diary-card-title {
  font-family: var(--font-display);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-size: 1.5rem;
  color: var(--ink);
}

.diary-page .diary-card--numbered .diary-card-inner {
  grid-template-columns: minmax(3rem, auto) minmax(0, 1fr);
  column-gap: 1rem;
}

.diary-page .diary-card--numbered .diary-card-index {
  font-family: var(--font-display);
  font-size: 4rem;
  color: var(--accent);
  border-bottom: 2px solid var(--accent);
  line-height: 0.8;
}

.diary-page .diary-card--numbered .diary-card-title {
  font-family: var(--font-display);
  text-transform: uppercase;
  letter-spacing: 0.03em;
  font-size: 1.4rem;
  color: var(--ink);
}

.diary-page .diary-card--timeline .diary-card-inner {
  padding-left: 2rem;
}

.diary-page .diary-card--timeline .diary-card-inner::before {
  left: 0.35rem;
  background: var(--accent);
  opacity: 0.3;
}

.diary-page .diary-card--timeline .diary-card-inner::after {
  left: 0;
  background: var(--accent);
  box-shadow: 0 0 0 4px var(--paper);
}

.diary-page .diary-card--timeline .diary-card-title {
  font-family: var(--font-display);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-size: 1.5rem;
  color: var(--ink);
}

.diary-page .diary-card-thread {
  border-color: var(--accent);
  color: var(--accent);
  font-family: var(--font-ui);
  background: transparent;
}

.diary-page .diary-card-thread:hover {
  background: var(--accent);
  color: var(--accent-ink);
}

.diary-page .diary-markets-label,
.diary-page .diary-spark-label {
  color: var(--muted);
}

.diary-page .diary-spark {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
  transition: box-shadow 200ms;
}

.diary-page .diary-spark:hover {
  box-shadow: 0 8px 24px -12px rgba(163, 74, 0, 0.2);
}

.diary-page .diary-spark-value {
  color: var(--ink);
}

.diary-page .diary-spark.is-down .diary-spark-change,
.diary-page .diary-spark.is-down {
  color: var(--accent);
}

.diary-page .diary-spark.is-up .diary-spark-change,
.diary-page .diary-spark.is-up {
  color: var(--ink);
}

.diary-page .diary-spark-line polyline {
  stroke: var(--accent);
  stroke-width: 2;
}

.diary-page .diary-footer {
  border-top: 2px solid var(--accent);
}

.diary-page .diary-footer a {
  color: var(--ink);
}

.diary-page .diary-footer a:hover {
  color: var(--accent);
}

.diary-page .diary-prose hr {
  border-top-color: var(--rule);
}

.diary-page .diary-prose code,
.diary-page .diary-prose pre {
  background: var(--paper-alt);
  border-color: var(--rule);
  color: var(--ink);
}

@media (max-width: 1023px) {
  .diary-page .diary-toc {
    border-bottom: 2px solid var(--accent);
  }
}

@media (min-width: 1024px) {
  .diary-page[data-hero="split"] .diary-hero-inner {
    grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr);
    column-gap: 4rem;
    align-items: end;
  }

  .diary-page[data-hero="split"] .diary-title {
    grid-row: 3 / span 2;
  }

  .diary-page .diary-toc {
    background: none;
  }
}
